widget.solution:
def cycle_windows(day0, form=252, trade=126):
    """((f0, f1), (t0, t1)): half-open formation and trading ranges."""
    return (day0, day0 + form), (day0 + form, day0 + form + trade)


def live_portfolios(month, K=6):
    """Portfolios (by first trading month, from 0) trading in this month, oldest first."""
    return list(range(max(0, month - K + 1), month + 1))
